ALTER TABLE public.clients ADD COLUMN video_token text UNIQUE DEFAULT encode(gen_random_bytes(18),'hex');
UPDATE public.clients SET video_token=encode(gen_random_bytes(18),'hex') WHERE video_token IS NULL;
CREATE TABLE public.video_projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), client_id uuid NOT NULL REFERENCES public.clients(id), month date NOT NULL, slot int NOT NULL CHECK(slot>0), title text NOT NULL, brief text NOT NULL DEFAULT '', platform text[] NOT NULL DEFAULT '{instagram}', due_date date, status text NOT NULL DEFAULT 'concept' CHECK(status IN ('concept','assets_klaar','in_productie','ter_review','revisie_gevraagd','in_revisie','goedgekeurd','afgerond')), revisions_included int NOT NULL DEFAULT 1 CHECK(revisions_included=1), revisions_used int NOT NULL DEFAULT 0 CHECK(revisions_used BETWEEN 0 AND 1), approved_at timestamptz, notify_client boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(client_id,month,slot), CHECK(platform <@ ARRAY['instagram','tiktok','youtube','facebook']::text[]));
GRANT SELECT,INSERT,UPDATE ON public.video_projects TO authenticated; GRANT DELETE ON public.video_projects TO authenticated; GRANT ALL ON public.video_projects TO service_role;
ALTER TABLE public.video_projects ENABLE ROW LEVEL SECURITY;
CREATE POLICY staff_read ON public.video_projects FOR SELECT TO authenticated USING(public.is_staff(auth.uid()));
CREATE POLICY staff_insert ON public.video_projects FOR INSERT TO authenticated WITH CHECK(public.is_staff(auth.uid()));
CREATE POLICY staff_update ON public.video_projects FOR UPDATE TO authenticated USING(public.is_staff(auth.uid())) WITH CHECK(public.is_staff(auth.uid()));
CREATE POLICY admin_delete ON public.video_projects FOR DELETE TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.video_assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), video_project_id uuid NOT NULL REFERENCES public.video_projects(id), kind text NOT NULL CHECK(kind IN ('asset','versie')), version int, storage_path text NOT NULL UNIQUE, mime_type text NOT NULL, thumb_path text, caption text NOT NULL DEFAULT '', sort_order int NOT NULL DEFAULT 0, uploaded_by text NOT NULL CHECK(uploaded_by IN ('solyn','client')), created_at timestamptz NOT NULL DEFAULT now(), CHECK((kind='asset' AND version IS NULL) OR (kind='versie' AND version IN (1,2))));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.video_assets TO authenticated; GRANT ALL ON public.video_assets TO service_role;
ALTER TABLE public.video_assets ENABLE ROW LEVEL SECURITY;
CREATE POLICY staff_read ON public.video_assets FOR SELECT TO authenticated USING(public.is_staff(auth.uid()));
CREATE POLICY staff_insert ON public.video_assets FOR INSERT TO authenticated WITH CHECK(public.is_staff(auth.uid()));
CREATE POLICY staff_update ON public.video_assets FOR UPDATE TO authenticated USING(public.is_staff(auth.uid())) WITH CHECK(public.is_staff(auth.uid()));
CREATE POLICY admin_delete ON public.video_assets FOR DELETE TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE UNIQUE INDEX video_one_version ON public.video_assets(video_project_id,version) WHERE kind='versie';
CREATE TABLE public.video_feedback (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), video_project_id uuid NOT NULL REFERENCES public.video_projects(id), version int NOT NULL CHECK(version IN (1,2)), decision text NOT NULL CHECK(decision IN ('goedgekeurd','aanpassen','extra_betalend')), comment text NOT NULL DEFAULT '', timestamps jsonb NOT NULL DEFAULT '[]', attachments jsonb NOT NULL DEFAULT '[]', contact_name text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), seen_at timestamptz, request_id uuid REFERENCES public.client_requests(id), task_id uuid REFERENCES public.client_tasks(id), email_error text);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.video_feedback TO authenticated; GRANT ALL ON public.video_feedback TO service_role;
ALTER TABLE public.video_feedback ENABLE ROW LEVEL SECURITY;
CREATE POLICY staff_read ON public.video_feedback FOR SELECT TO authenticated USING(public.is_staff(auth.uid()));
CREATE POLICY staff_insert ON public.video_feedback FOR INSERT TO authenticated WITH CHECK(public.is_staff(auth.uid()));
CREATE POLICY staff_update ON public.video_feedback FOR UPDATE TO authenticated USING(public.is_staff(auth.uid())) WITH CHECK(public.is_staff(auth.uid()));
CREATE POLICY admin_delete ON public.video_feedback FOR DELETE TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.video_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), video_project_id uuid NOT NULL REFERENCES public.video_projects(id), label text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.video_events TO authenticated; GRANT ALL ON public.video_events TO service_role;
ALTER TABLE public.video_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY staff_read ON public.video_events FOR SELECT TO authenticated USING(public.is_staff(auth.uid()));
CREATE POLICY staff_insert ON public.video_events FOR INSERT TO authenticated WITH CHECK(public.is_staff(auth.uid()));
CREATE POLICY staff_update ON public.video_events FOR UPDATE TO authenticated USING(public.is_staff(auth.uid())) WITH CHECK(public.is_staff(auth.uid()));
CREATE POLICY admin_delete ON public.video_events FOR DELETE TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.video_uploads(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), video_project_id uuid NOT NULL REFERENCES public.video_projects(id), storage_path text NOT NULL UNIQUE, mime_type text NOT NULL, size bigint NOT NULL CHECK(size>0 AND size<=524288000), kind text NOT NULL, version int, uploaded_by text NOT NULL, caption text NOT NULL DEFAULT '', completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.video_uploads TO service_role;
ALTER TABLE public.video_uploads ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.video_log_status() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' OR NEW.status IS DISTINCT FROM OLD.status THEN INSERT INTO public.video_events(video_project_id,label) VALUES(NEW.id,NEW.status); END IF; NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER video_status_event AFTER INSERT OR UPDATE OF status ON public.video_projects FOR EACH ROW EXECUTE FUNCTION public.video_log_status();
CREATE TRIGGER video_updated BEFORE UPDATE ON public.video_projects FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE FUNCTION public.video_decide(_client uuid,_video uuid,_version int,_decision text,_comment text,_timestamps jsonb,_attachments jsonb,_name text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE p public.video_projects; f uuid; r uuid; t uuid; c text; details text; BEGIN
SELECT * INTO p FROM public.video_projects WHERE id=_video AND client_id=_client FOR UPDATE;
IF NOT FOUND OR p.status<>'ter_review' THEN RAISE EXCEPTION 'Deze video wacht niet op feedback.'; END IF;
IF _version<>(SELECT max(version) FROM public.video_assets WHERE video_project_id=p.id AND kind='versie') THEN RAISE EXCEPTION 'Bekijk de nieuwste versie.'; END IF;
IF _decision NOT IN ('goedgekeurd','aanpassen','extra_betalend') THEN RAISE EXCEPTION 'Ongeldige keuze'; END IF;
IF _decision='aanpassen' AND (p.revisions_used>0 OR _version<>1) THEN RAISE EXCEPTION 'Je revisie is gebruikt.'; END IF;
IF _decision='extra_betalend' AND (p.revisions_used<>1 OR _version<>2) THEN RAISE EXCEPTION 'Extra aanpassing alleen na revisie.'; END IF;
IF _decision<>'goedgekeurd' AND length(trim(_comment))=0 THEN RAISE EXCEPTION 'Wat wil je anders?'; END IF;
SELECT name INTO c FROM public.clients WHERE id=_client;
IF _decision<>'goedgekeurd' THEN
SELECT coalesce(string_agg(lpad((floor((x->>'seconds')::numeric/60))::text,2,'0')||':'||lpad((floor((x->>'seconds')::numeric)%60)::text,2,'0')||' '||coalesce(x->>'note',''),E'\n'),'') INTO details FROM jsonb_array_elements(_timestamps) x;
INSERT INTO public.client_tasks(client_id,title,assignee,due_date) VALUES(_client,'Revisie: '||p.title||' ('||c||')','me',(now() AT TIME ZONE 'Europe/Brussels')::date+2) RETURNING id INTO t;
INSERT INTO public.client_requests(client_id,title,kind,details,status,note,task_id,contact_name,attachments) VALUES(_client,'Video revisie — '||p.title,'social',_comment||E'\n'||details,'nieuw',CASE WHEN _decision='extra_betalend' THEN 'Extra aanpassing (betalend) — apart aanrekenen' ELSE '1 inbegrepen revisie' END,t,_name,_attachments) RETURNING id INTO r;
IF _decision='aanpassen' THEN UPDATE public.video_projects SET status='revisie_gevraagd',revisions_used=1 WHERE id=p.id; END IF;
ELSE
UPDATE public.video_projects SET status='goedgekeurd',approved_at=now() WHERE id=p.id;
INSERT INTO public.client_videos(client_id,month,slot,status,sent_at) VALUES(_client,p.month,p.slot,'verstuurd',now()) ON CONFLICT(client_id,month,slot) DO UPDATE SET status='verstuurd',sent_at=EXCLUDED.sent_at;
UPDATE public.client_tasks SET done_at=now() WHERE id IN (SELECT task_id FROM public.video_feedback WHERE video_project_id=p.id) AND done_at IS NULL;
END IF;
INSERT INTO public.video_feedback(video_project_id,version,decision,comment,timestamps,attachments,contact_name,request_id,task_id) VALUES(p.id,_version,_decision,_comment,_timestamps,_attachments,_name,r,t) RETURNING id INTO f;
RETURN f; END $$;
REVOKE ALL ON FUNCTION public.video_decide(uuid,uuid,int,text,text,jsonb,jsonb,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.video_decide(uuid,uuid,int,text,text,jsonb,jsonb,text) TO service_role;
CREATE POLICY video_storage_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='client-videos' AND public.is_staff(auth.uid()));
CREATE POLICY video_storage_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='client-videos' AND public.is_staff(auth.uid()) AND EXISTS(SELECT 1 FROM public.video_projects p WHERE p.client_id::text=(storage.foldername(name))[1] AND p.id::text=(storage.foldername(name))[2]));
CREATE POLICY video_storage_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='client-videos' AND public.has_role(auth.uid(),'admin'));
CREATE INDEX video_projects_client ON public.video_projects(client_id,month DESC);
CREATE INDEX video_feedback_unseen ON public.video_feedback(created_at) WHERE seen_at IS NULL;